import{_ as a,o as n,c as e,a6 as t}from"./chunks/framework.BrkgobfX.js";const d=JSON.parse('{"title":"缓存失效 · TTL、按路径、按标签、按需","description":"「计算机科学只有两件难事：缓存失效和命名。」数据变了、缓存却还旧着，怎么让它精准更新？这一章讲清基于时间(TTL)与按需（事件驱动）两大流派，以及按路径、按标签失效——尤其是标签如何破解「哪些页面依赖这份数据」的难题。","frontmatter":{"title":"缓存失效 · TTL、按路径、按标签、按需","description":"「计算机科学只有两件难事：缓存失效和命名。」数据变了、缓存却还旧着，怎么让它精准更新？这一章讲清基于时间(TTL)与按需（事件驱动）两大流派，以及按路径、按标签失效——尤其是标签如何破解「哪些页面依赖这份数据」的难题。","source":"https://daiw.org/manual/ssr/cache-invalidation"},"headers":[],"relativePath":"manual/computer-programming/ssr/cache-invalidation.md","filePath":"manual/computer-programming/ssr/cache-invalidation.md"}'),r={name:"manual/computer-programming/ssr/cache-invalidation.md"};function i(l,s,o,p,g,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="缓存失效-·-ttl、按路径、按标签、按需" tabindex="-1">缓存失效 · TTL、按路径、按标签、按需 <a class="header-anchor" href="#缓存失效-·-ttl、按路径、按标签、按需" aria-label="Permalink to &quot;缓存失效 · TTL、按路径、按标签、按需&quot;">​</a></h1><p>「计算机科学只有两件难事：缓存失效和命名。」数据变了、缓存却还旧着，怎么让它精准更新？这一章讲清基于时间(TTL)与按需（事件驱动）两大流派，以及按路径、按标签失效——尤其是标签如何破解「哪些页面依赖这份数据」的难题。</p><p>有句在程序员圈流传甚广的话：</p><blockquote><p><strong>「计算机科学里只有两件难事：缓存失效，和给东西起名字。」</strong>——Phil Karlton</p></blockquote><p>缓存本身不难，难的是<strong>失效</strong>：数据已经变了，可缓存里还是旧的，怎么让它<strong>在恰当的时机、精准地</strong>更新？这一章就攻这件「两大难事」之一。</p><h2 id="两大流派-被动过期-vs-主动失效" tabindex="-1">两大流派：被动过期 vs 主动失效 <a class="header-anchor" href="#两大流派-被动过期-vs-主动失效" aria-label="Permalink to &quot;两大流派：被动过期 vs 主动失效&quot;">​</a></h2><p>缓存失效的所有做法，归根到底就两派：</p><ul><li><strong>基于时间（被动）</strong>：给缓存设个 TTL，时间一到自动过期——就是前面的 <code>max-age</code>、<a href="/Front2Full/manual/computer-programming/ssr/swr">SWR</a>、<a href="/Front2Full/manual/computer-programming/ssr/isr">ISR 的 <code>revalidate</code></a>。<strong>简单、零维护</strong>，但永远有个「最长陈旧窗口」，而且<strong>你没法在数据一变就立刻刷新</strong>——只能等它自己过期。</li><li><strong>按需（主动 / 事件驱动）</strong>：数据一发生变化，就<strong>主动去把受影响的缓存清掉 / 重新生成</strong>。<strong>精准、即时</strong>，但你得<strong>知道该清哪些</strong>，还得在<strong>每一处写数据的地方</strong>都记得触发失效。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>最佳实践通常是两者叠用：TTL 兜底 + 按需精修。</strong> 用一个较长的 TTL（比如 1 小时）当<strong>安全网</strong>——就算你哪次忘了主动失效，内容最多旧一小时也会自愈；同时在关键的写路径上做<strong>按需失效</strong>，让重要变更<strong>秒级生效</strong>。被动保正确性下限，主动保新鲜度上限。<strong>只靠按需，漏一处就永久旧；只靠 TTL，新鲜度永远差一截。</strong></p></div><h2 id="按需失效的粒度-路径-vs-标签" tabindex="-1">按需失效的粒度：路径 vs 标签 <a class="header-anchor" href="#按需失效的粒度-路径-vs-标签" aria-label="Permalink to &quot;按需失效的粒度：路径 vs 标签&quot;">​</a></h2><p>主动失效最核心的问题是：<strong>「清哪些」</strong>。有两种指定方式，难度天差地别。</p><p><strong>按路径(by path)</strong> —— 直接点名要清的 URL：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">revalidatePath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/article/42&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>直观，但有个致命短板：<strong>你得自己想全「这份数据出现在哪些页面上」。</strong> 文章 42 改了，受影响的不只是 <code>/article/42</code>——还有首页的最新列表、<code>/tag/xxx</code> 标签页、作者页、RSS……<strong>漏掉任何一个，那页就永久显示旧数据。</strong> 依赖关系一复杂，按路径失效就极易出错。</p><p><strong>按标签(by tag)</strong> —— 这才是破局的关键。给<strong>数据</strong>打标签，渲染用到该数据的<strong>每个页面</strong>都自动带上这个标签；数据一变，<strong>按标签一键清掉所有带它的页面</strong>，不管它们在哪个路径：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 取数时打标签(或在 Next.js 16 的 &#39;use cache&#39; 函数中调用 cacheTag(&#39;article-42&#39;))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/article/42&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { next: { tags: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;article-42&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } });</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 文章 42 一改,清掉所有用到它的页面——不用你去想有哪些</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">revalidateTag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;article-42&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  X[&quot;文章 42 被编辑&quot;] --&gt; T[&quot;revalidateTag(&#39;article-42&#39;)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  T --&gt; P1[&quot;/article/42&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  T --&gt; P2[&quot;首页最新列表&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  T --&gt; P3[&quot;/tag/前端&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  T --&gt; P4[&quot;作者页&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>标签解决的，正是失效里最难的那部分——依赖图。</strong> 「哪些页面依赖这份数据」这个问题，人脑很难维护周全；标签把它<strong>反过来</strong>：不是你去追踪「数据 → 页面」，而是每个页面在渲染时<strong>自己声明</strong>「我用了带这个标签的数据」。于是失效时只需喊一声标签，框架自动找齐所有相关页面。<strong>能用标签，就别用手写路径清单。</strong></p></div><h2 id="cdn-层的失效-purge-与传播延迟" tabindex="-1">CDN 层的失效：purge 与传播延迟 <a class="header-anchor" href="#cdn-层的失效-purge-与传播延迟" aria-label="Permalink to &quot;CDN 层的失效：purge 与传播延迟&quot;">​</a></h2><p>上面是框架层。到了 <a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">CDN 层</a>，主动失效叫 <strong>purge（清除）</strong>，同样有几种粒度：</p><ul><li><strong>按 URL purge</strong>：清单个页面，最精准。</li><li><strong>按标签 / surrogate key purge</strong>：CDN 也支持缓存标签（Fastly 的 surrogate key、Cloudflare 的 cache tag），一次清一批，和框架标签是同一个思路。</li><li><strong>purge everything（清空）</strong>：核弹级，清掉整站缓存。<strong>慎用</strong>——清空后所有请求瞬间全部未命中、一起回源，等于自己制造一次<a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">缓存击穿</a>。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>CDN 的 purge 不是瞬间全球生效的。</strong> CDN 有全球几百个节点，一次 purge 要<strong>传播</strong>到所有节点，通常是<strong>秒级</strong>（偶尔更久）。所以「点了保存，线上却还没变」有时不是 bug，是 purge 还在传播。设计时要接受这个<strong>最终一致</strong>的现实：失效是「很快」，不是「瞬间」。真要求「写完立刻一定看到最新」，得绕过缓存直接回源读那一次。</p></div><h2 id="触发时机-webhook-串起来" tabindex="-1">触发时机：webhook 串起来 <a class="header-anchor" href="#触发时机-webhook-串起来" aria-label="Permalink to &quot;触发时机：webhook 串起来&quot;">​</a></h2><p>按需失效怎么被触发？最常见的是 <strong>webhook</strong>：内容源（CMS、数据库、后台）在数据变更时，<strong>主动打一个 HTTP 请求</strong>到你的站点的失效接口，带上「变的是什么」，你的接口据此 <code>revalidateTag</code> / purge。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>编辑在 CMS 点「保存」</span></span>
<span class="line"><span>      → CMS 发 webhook:POST /api/revalidate { tag: &quot;article-42&quot; }</span></span>
<span class="line"><span>      → 你的接口:revalidateTag(&#39;article-42&#39;) + CDN purge tag</span></span>
<span class="line"><span>      → 秒级,线上更新</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这条链把「数据变更」和「缓存失效」自动焊在一起——编辑不必懂缓存，点保存就行。</p><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>缓存失效分<strong>被动过期（TTL，简单但有陈旧窗口）</strong> 和<strong>按需失效（精准但要接线）</strong>，最佳实践是两者叠用。按需失效的粒度里，<strong>按标签</strong>远胜按路径——它把「哪些页面依赖这份数据」这个最难的依赖图问题，交给页面自己声明。CDN 层对应 purge，注意它是最终一致、有传播延迟。</p><p>现在，缓存这一站只剩最后、也是最硬的一块骨头了：<strong>个性化内容</strong>。「你好，张三」这种每人不同的页面，天生和「共享缓存」水火不容——可我们又想要 CDN 的速度。这个两难怎么破？下一章，缓存的压轴。👉 <a href="/Front2Full/manual/computer-programming/ssr/personalization">个性化与缓存：每人不同的页面怎么缓存</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Next.js 文档.「revalidateTag / revalidatePath.」<a href="https://nextjs.org/docs/app/api-reference/functions/revalidateTag" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/api-reference/functions/revalidateTag</a> —— 按标签 / 按路径失效。</li><li>[2] Fastly.「Purging with surrogate keys.」<a href="https://docs.fastly.com/en/guides/working-with-surrogate-keys" target="_blank" rel="noreferrer">https://docs.fastly.com/en/guides/working-with-surrogate-keys</a> —— 标签式 CDN purge。</li><li>[3] Cloudflare.「Purge cache by cache-tag / URL.」<a href="https://developers.cloudflare.com/cache/how-to/purge-cache/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/cache/how-to/purge-cache/</a> —— CDN 失效与传播。</li></ul>`,31)])])}const u=a(r,[["render",i]]);export{d as __pageData,u as default};
